mapper.select:
SELECT c.ch_num AS chNum, c.ch_level AS chLevel, c.ch_exp AS chExp, c.user_num AS userNum, c.cg_num AS cgNum, cg.cg_name AS cgName, cg.cg_img AS cgImg,
(SELECT COALESCE(MAX(he_exp), 0) FROM highest_exp WHERE he_level < c.ch_level) AS currentLevelExp,
(SELECT MIN(he_exp) FROM highest_exp WHERE he_level > c.ch_level) AS nextLevelExp FROM `character` c JOIN character_grow cg ON c.cg_num = cg.cg_num WHERE c.user_num = #{userNum}

mapper.update:
UPDATE `character`
SET ch_exp = #{chExp},
    ch_level = #{chLevel},
    cg_num = #{cgNum}
WHERE user_num = #{userNum}
